 44→export const loader = async ({ request }: LoaderFunctionArgs) => {
 45→  const { session } = await authenticate.admin(request);
 46→  const shop = session.shop;
 47→
 48→  const rules = await db.deliveryRule.findMany({
 49→    where: { shop },
 50→    orderBy: { priority: "asc" },
 51→  });
 52→
 53→  // Get unique zones from zip codes for dropdown
 54→  const zones = await db.zipCode.findMany({
 55→    where: { shop, zone: { not: null } },
 56→    select: { zone: true },
 57→    distinct: ["zone"],
 58→  });
 59→
 60→  return {
 61→    rules,
 62→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
 63→  };
 64→};
